// Generated by scripts/sync-core.mjs from mobile/src/state/keystore.ts; edit it there and run npm run sync-core.
// Secrets live in the platform keystore (SecureStore) on phones. The browser
// has no equivalent, so the web build keeps them in localStorage, which only
// the browser's own protections guard.
import { Platform } from 'react-native';
import * as Crypto from 'expo-crypto';
import * as SecureStore from 'expo-secure-store';

const PREFIX = 'ting.key.';
/** Only on this device, and only while it is unlocked: iOS leaves such items out of backups and transfers to a new phone. */
const OPTIONS: SecureStore.SecureStoreOptions = { keychainAccessible: SecureStore.WHEN_UNLOCKED_THIS_DEVICE_ONLY };

export const KEYSTORE_NOTE =
  Platform.OS === 'web'
    ? 'Keys are kept in this browser’s local storage.'
    : 'Keys are kept in the device keystore and never leave this device.';

export function randomBytes(n: number): Uint8Array {
  return Crypto.getRandomBytes(n);
}

export function uuid(): string {
  return Crypto.randomUUID();
}

async function read(name: string): Promise<string | null> {
  if (Platform.OS === 'web') return globalThis.localStorage?.getItem(name) ?? null;
  return SecureStore.getItemAsync(name, OPTIONS);
}

async function write(name: string, value: string): Promise<void> {
  if (Platform.OS === 'web') {
    globalThis.localStorage?.setItem(name, value);
    return;
  }
  await SecureStore.setItemAsync(name, value, OPTIONS);
}

async function remove(name: string): Promise<void> {
  if (Platform.OS === 'web') {
    globalThis.localStorage?.removeItem(name);
    return;
  }
  await SecureStore.deleteItemAsync(name, OPTIONS);
}

export async function saveSecret(keyId: string, secretHex: string): Promise<void> {
  await write(PREFIX + keyId, secretHex);
}

export async function loadSecret(keyId: string): Promise<string | null> {
  return read(PREFIX + keyId);
}

export async function deleteSecret(keyId: string): Promise<void> {
  await remove(PREFIX + keyId);
}
